/*
 * prog24_query_string_parser.c
 *
 * The original binary parses a single line read from stdin that contains a
 * URL‑encoded query string (e.g.  "name=John+Doe&city=New%20York").
 * It URL‑decodes each key and value and prints them as
 *
 *      key=value
 *
 * one pair per line.  If no line is supplied (EOF) it prints the literal
 * string "NO_INPUT".
 *
 * The implementation below reproduces the observable behaviour of the
 * obfuscated binary while keeping the code clear and idiomatic.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 0x800          /* 2048 bytes – same size used by the binary */

/* --------------------------------------------------------------------- */
/* URL‑decode a substring.
 *
 *  src   – pointer to the encoded data
 *  len   – number of bytes to decode
 *  dst   – buffer where the decoded string is written (null‑terminated)
 *
 * The decoder implements the standard rules used by the original program:
 *   '+'  -> space
 *   "%XY" where X and Y are hex digits -> byte value 0xXY
 *   any other character -> copied unchanged
 * --------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, j = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {                     /* plus becomes space */
            dst[j++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* convert two hex digits */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' :
                      (toupper((unsigned char)hi) - 'A' + 10));
            val = (val << 4) |
                  (isdigit((unsigned char)lo) ? lo - '0' :
                  (toupper((unsigned char)lo) - 'A' + 10));
            dst[j++] = (char)val;
            i += 3;
        } else {                            /* ordinary character */
            dst[j++] = c;
            i++;
        }
    }
    dst[j] = '\0';
}

/* --------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_LINE];
    static char val[MAX_LINE];

    /* read a line from stdin – exactly what the original binary does */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* strip trailing newline and optional carriage‑return */
    size_t len = strlen(line);
    if (len && line[len - 1] == '\n') {
        line[--len] = '\0';
        if (len && line[len - 1] == '\r')
            line[--len] = '\0';
    }

    /* parse the query string: key=value pairs separated by '&' */
    size_t pos = 0;
    while (pos < len) {
        size_t seg_start = pos;                     /* start of this segment */
        while (pos < len && line[pos] != '&')
            ++pos;
        size_t seg_len = pos - seg_start;           /* length of the segment */

        /* locate the first '=' inside the segment, if any */
        size_t eq = seg_start;
        while (eq < seg_start + seg_len && line[eq] != '=')
            ++eq;

        size_t key_len, val_len;
        if (eq < seg_start + seg_len) {             /* '=' found */
            key_len = eq - seg_start;
            val_len = seg_start + seg_len - (eq + 1);
        } else {                                    /* no '=', whole segment is the key */
            key_len = seg_len;
            val_len = 0;
        }

        /* decode key */
        url_decode(line + seg_start, key_len, key);

        /* decode value (or make it empty) */
        if (val_len > 0)
            url_decode(line + eq + 1, val_len, val);
        else
            val[0] = '\0';

        /* output the pair */
        printf("%s=%s\n", key, val);

        /* skip the '&' separator, if present */
        if (pos < len && line[pos] == '&')
            ++pos;
    }

    return 0;
}
